shellCommands.command:
/bin/bash -lc "cat > src/styles.css <<'EOF'
*, *::before, *::after { box-sizing: border-box; }

.g-root {
  --g-color-base-brand: var(--g-color-text-primary);
  --g-color-base-brand-hover: var(--g-color-text-utility-heavy);
  --g-color-base-selection: var(--g-color-base-utility-light);
  --g-color-base-selection-hover: var(--g-color-base-utility-medium);
  --g-color-line-brand: var(--g-color-line-utility);
  --g-color-line-focus: var(--g-color-text-utility);
  --g-color-text-brand: var(--g-color-text-utility);
  --g-color-text-brand-heavy: var(--g-color-text-utility-heavy);
  --g-color-text-brand-contrast: var(--g-color-base-background);
  --g-color-text-link: var(--g-color-text-utility);
  --g-color-text-link-hover: var(--g-color-text-utility-heavy);
  --g-color-text-link-visited: var(--g-color-text-utility);
  --g-text-accent-font-weight: 500;
  --g-text-display-4-font-size: clamp(42px, 6.2vw, 80px);
  --g-text-display-4-line-height: 1.08;
  --g-text-header-1-font-size: 20px;
  --g-text-header-1-line-height: 1.35;
  --g-text-display-2-font-size: 30px;
  --g-text-display-2-line-height: 1.2;
  --g-text-body-2-font-size: 15px;
  --g-text-body-2-line-height: 1.7;
  --pc-text-header-color: var(--g-color-text-primary);
  --pc-border-radius: var(--g-border-radius-xl);
}

body { margin: 0; background: var(--g-color-base-background); }
.landing { max-width: 1440px; margin: 0 auto; padding: var(--g-spacing-8); }
.hero-intro { display: flex; align-items: center; flex-direction: column; gap: var(--g-spacing-8); margin-bottom: var(--g-spacing-8); }
.wordmark { font-weight: 700; letter-spacing: -2px; }
.wordmark span, .hero-accent { color: var(--g-color-text-utility); }
.eyebrow {
  font-size: var(--g-text-body-1-font-size);
  line-height: var(--g-text-body-1-line-height);
  border: 1px solid var(--g-color-line-utility);
  border-radius: var(--g-border-radius-xl);
  padding: var(--g-spacing-2) var(--g-spacing-4);
  color: var(--g-color-text-utility-heavy);
}

/* Narrow layout overrides for Page Constructor 8.24.1. These blocks expose
   no CSS API for title tracking, feature separators or a horizontal banner.
   Keep scoped here; candidates for upstream layout customization props. */
.landing .pc-header-block { border-radius: var(--g-border-radius-xl); overflow: hidden; margin: 0; padding: 0; }
.landing .pc-header-block__content_vertical-offset_s { margin: 0; padding: var(--g-spacing-8) 0 var(--g-spacing-10); }
.landing .pc-header-block__title { letter-spacing: -0.055em; }
.landing .pc-header-block__description { margin-top: var(--g-spacing-6); }
.landing .pc-header-block__description .yfm { font-size: 18px; line-height: 1.65; color: var(--g-color-text-secondary); }
.landing .pc-header-block__additional-info { margin-top: var(--g-spacing-7); color: var(--g-color-text-secondary); font-size: var(--g-text-body-1-font-size); }
.landing .pc-ExtendedFeaturesBlock { padding: var(--g-spacing-7) 0; counter-reset: feature; }
.landing .pc-ExtendedFeaturesBlock__item { padding-inline: var(--g-spacing-8); min-width: 0; counter-increment: feature; }
.landing .pc-ExtendedFeaturesBlock__item + .pc-ExtendedFeaturesBlock__item { border-left: 1px solid var(--g-color-line-generic); }
.landing .pc-ExtendedFeaturesBlock__container::before {
  content: '0' counter(feature);
  display: block;
  margin-bottom: var(--g-spacing-5);
  font-size: var(--g-text-body-1-font-size);
  font-variant-numeric: tabular-nums;
  color: var(--g-color-text-utility);
}
.landing .pc-ExtendedFeaturesBlock__item-title { letter-spacing: -0.025em; }
.landing .pc-ExtendedFeaturesBlock .pc-content { color: var(--g-color-text-secondary); }
.landing .pc-banner-card__content { min-height: 0; }
.landing .pc-banner-card__info { flex-direction: row; align-items: center; gap: var(--g-spacing-8); padding: var(--g-spacing-10); }
.landing .pc-banner-card__text { flex: 1; min-width: 0; }
.landing .pc-banner-card__title { letter-spacing: -0.035em; }
.landing .pc-banner-card__subtitle { color: var(--g-color-text-secondary); font-size: var(--g-text-body-2-font-size); }
.landing .pc-banner-card__button { --g-button-border-radius: var(--g-border-radius-m); margin: 0; flex-shrink: 0; }

@media (max-width: 768px) {
  .landing { padding: var(--g-spacing-4); }
  .hero-intro { gap: var(--g-spacing-6); }
  .desktop-break { display: none; }
  .landing .pc-header-block__description .yfm { font-size: var(--g-text-body-2-font-size); }
  .landing .pc-ExtendedFeaturesBlock__item { padding: 0 var(--g-spacing-3) var(--g-spacing-6); }
  .landing .pc-ExtendedFeaturesBlock__item + .pc-ExtendedFeaturesBlock__item { border-left: 0; border-top: 1px solid var(--g-color-line-generic); padding-top: var(--g-spacing-7); margin-top: 0; }
  .landing .pc-banner-card__info { flex-direction: column; align-items: flex-start; gap: var(--g-spacing-6); padding: var(--g-spacing-7); }
}
EOF
npm run build > /tmp/takt-build.log 2>&1
tail -55 /tmp/takt-build.log"
